export const TYPES={switch:{name:'Ethernet switch',short:'SW',width:4,model:'Stratix 5700',color:'#488f92'},plc:{name:'PLC controller',short:'PLC',width:3,model:'CompactLogix 5380',color:'#608b69'},io:{name:'Remote I/O',short:'I/O',width:2,model:'POINT I/O 1734',color:'#86909b'},vfd:{name:'VFD drive',short:'VFD',width:3,model:'PowerFlex 525',color:'#b7a06d'},hmi:{name:'HMI terminal',short:'HMI',width:3,model:'PanelView 800',color:'#5c85a8'},gateway:{name:'Network gateway',short:'GW',width:2,model:'Industrial gateway',color:'#9b85ae'}};
export function seed(){
const panels=[{id:'idf-01',name:'IDF-01',title:'Main distribution',area:'Network room',x:184,y:173,subnet:0,types:['switch','gateway','switch','hmi','io']},{id:'cp-01',name:'CP-01',title:'Assembly line A',area:'Assembly',x:455,y:243,subnet:1,types:['switch','plc','io','vfd','vfd','hmi']},{id:'cp-02',name:'CP-02',title:'Assembly line B',area:'Assembly',x:735,y:243,subnet:2,types:['switch','plc','io','vfd','vfd','hmi']},{id:'mcc-01',name:'MCC-01',title:'Motor control center',area:'Utilities',x:183,y:488,subnet:3,types:['switch','plc','vfd','vfd','vfd']},{id:'cp-03',name:'CP-03',title:'Packaging & palletizing',area:'Packaging',x:520,y:503,subnet:4,types:['switch','plc','io','vfd','hmi']},{id:'idf-02',name:'IDF-02',title:'Warehouse distribution',area:'Warehouse',x:898,y:472,subnet:0,types:['switch','gateway','io','hmi','plc']}];
let devices=[];
panels.forEach((p,pi)=>{let row=0,slot=0;p.types.forEach((type,i)=>{const t=TYPES[type];if(slot+t.width>12){row++;slot=0;}const id=`${p.id}-${i+1}`;const names={switch:i===0?'Access switch':'Distribution switch',plc:'Line controller',io:'Remote I/O rack',vfd:`${p.id==='mcc-01'?'Pump':'Conveyor'} drive ${p.id==='mcc-01'?i-1:i-2}`,hmi:'Operator terminal',gateway:'Edge gateway'};devices.push({id,panelId:p.id,type,name:names[type],ip:`172.168.${p.subnet}.${pi===5?110+i:i===0?10:20+i}`,description:`${names[type]} serving ${p.title.toLowerCase()}. ${type==='switch'?'Connects this cabinet’s industrial Ethernet devices to the plant network.':type==='vfd'?'Controls motor speed and reports drive status to the line controller.':type==='plc'?'Coordinates the process sequence, interlocks, and connected field equipment.':type==='hmi'?'Provides local operator controls and process visualization.':type==='io'?'Collects field sensor inputs and controls local outputs.':'Bridges the local equipment network and supervisory systems.'}`,model:t.model,status:pi===3&&type==='vfd'&&i===4?'attention':'online',row,slot,connections:i===0?[]:[`${p.id}-1`]});slot+=t.width;});});
devices.find(d=>d.id==='cp-01-1').connections=['idf-01-1'];devices.find(d=>d.id==='cp-02-1').connections=['idf-01-1'];devices.find(d=>d.id==='mcc-01-1').connections=['idf-01-3'];devices.find(d=>d.id==='cp-03-1').connections=['idf-02-1'];devices.find(d=>d.id==='idf-02-1').connections=['idf-01-3'];return {version:1,panels:panels.map(({types,...p})=>p),devices};}
export function canPlace(devices,panelId,type,row,slot,exclude){if(!TYPES[type]||!Number.isInteger(row)||!Number.isInteger(slot)||row<0||row>2||slot<0||slot+TYPES[type].width>12)return false;return !devices.some(d=>d.panelId===panelId&&d.id!==exclude&&d.row===row&&slot<d.slot+TYPES[d.type].width&&slot+TYPES[type].width>d.slot);}
export function findSpace(devices,panelId,type,row){for(const r of row===undefined?[0,1,2]:[row])for(let slot=0;slot<=12-TYPES[type].width;slot++)if(canPlace(devices,panelId,type,r,slot))return {row:r,slot};return null;}
export function validIP(ip){return /^(\d{1,3}\.){3}\d{1,3}$/.test(ip)&&ip.split('.').every(n=>+n<=255&&String(+n)===n);}
export function validateData(data){if(data?.version!==1||!Array.isArray(data.panels)||!Array.isArray(data.devices)||data.panels.length!==6||data.devices.length>200)throw Error('Choose a valid Floorlink layout with six panels.');const ids=new Set(),ips=new Set(),pids=new Set();for(const p of data.panels){if(typeof p.id!=='string'||pids.has(p.id)||!['name','title','area'].every(k=>typeof p[k]==='string')||![p.x,p.y].every(Number.isFinite)||!Number.isInteger(p.subnet)||p.subnet<0||p.subnet>4||p.x<0||p.x>1100||p.y<0||p.y>700)throw Error('Invalid panel data.');pids.add(p.id);}for(const d of data.devices){if(typeof d.id!=='string'||ids.has(d.id)||!pids.has(d.panelId)||!TYPES[d.type]||!validIP(d.ip)||ips.has(d.ip)||!['name','description','model'].every(k=>typeof d[k]==='string')||!['online','attention','offline'].includes(d.status)||!Array.isArray(d.connections)||!canPlace(data.devices.filter(x=>x!==d),d.panelId,d.type,d.row,d.slot))throw Error('Layout contains invalid devices, duplicate IPs, or overlapping equipment.');ids.add(d.id);ips.add(d.ip);}for(const d of data.devices)if(d.connections.some(id=>!ids.has(id)||id===d.id))throw Error('A device connection is invalid.');return data;}
